import { z } from 'zod';

export const DOCUMENT_SUMMARY_PROMPT = `Analyze this document and provide a comprehensive summary with the following components:

1. **One-line summary** (max 100 characters): A brief description of the document's main focus
2. **Paragraph summary** (200-300 words): A detailed plot/content summary covering key events
3. **Scene breakdown**: Identify major scenes or sections with:
   - Scene number (starting from 1)
   - Character positions (approximate start/end character positions)
   - Brief summary of what happens
4. **Characters**: List all named characters that appear
5. **Character aliases**: For each character, list aliases, pronouns, and descriptive references used
6. **Locations**: List all specific locations mentioned
7. **Themes**: Identify 3-5 major themes
8. **Key events**: List 3-5 most important events or developments

CRITICAL RULES:
- Return ONLY information explicitly stated in the text
- NO interpretation, inference, or speculation
- NO information from other chapters or external knowledge
- NO spoilers or foreshadowing beyond what's directly stated
- Include character positions for scene boundaries`;

export const SceneSummarySchema = z.object({
  idx: z.number(),
  start: z.number(),
  end: z.number(),
  summary: z.string()
});

export const DocumentSummarySchema = z.object({
  oneLineSummary: z.string(),
  paragraphSummary: z.string(),
  sceneSummaries: z.array(SceneSummarySchema),
  characters: z.array(z.string()),
  characterAliases: z.record(z.string(), z.array(z.string())).optional().default({}),
  locations: z.array(z.string()),
  themes: z.array(z.string()),
  keyEvents: z.array(z.string())
});

export type SceneSummary = z.infer<typeof SceneSummarySchema>;
export type DocumentSummary = z.infer<typeof DocumentSummarySchema>;

export function buildDocumentSummaryPrompt(
  content: string,
  title: string,
  documentId: string
): string {
  return `${DOCUMENT_SUMMARY_PROMPT}

Document Title: ${title}
Document ID: ${documentId}

Content:
${content}

Generate the comprehensive summary in JSON format:`;
}